def _reproject_slice_cython(int startx, int endx, int starty, int endy, int nx_out, int ny_out,
    np.ndarray[double, ndim=2, mode = "c"] xp_inout,
    np.ndarray[double, ndim=2, mode = "c"] yp_inout,
