"""High-precision reference: area of intersection of two convex spherical quads."""
import numpy as np

LD = np.longdouble
PI = LD(np.pi) + LD(1.2246467991473532e-16)  # pi to ~ld precision? use series below instead

def _pi_ld():
    # Machin-like: pi = 16*atan(1/5) - 4*atan(1/239)
    def atan_inv(n):
        n = LD(n); term = LD(1)/n; s = LD(0); k = 0
        while True:
            t = term/(2*k+1) * ((-1)**k)
            s += t
            if abs(t) < LD(1e-40): break
            k += 1
            term /= n*n
        return s
    return 16*atan_inv(5) - 4*atan_inv(239)

PI = _pi_ld()

def unit_from_lonlat(lon_deg, lat_deg):
    lon = LD(lon_deg)*PI/LD(180); lat = LD(lat_deg)*PI/LD(180)
    return np.array([np.cos(lon)*np.cos(lat), np.sin(lon)*np.cos(lat), np.sin(lat)], dtype=LD)

def cross(a, b):
    return np.array([a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]], dtype=a.dtype)

def dot(a, b):
    return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]

def normalize(a):
    return a/np.sqrt(dot(a, a))

def edge_normal(a, b):
    """Normal of great circle through a,b, computed stably (perp to a by construction)."""
    return normalize(cross(a, b - a))

def orient(poly):
    """Return CCW-ordered polygon (positive signed area)."""
    if signed_area(poly) < 0:
        return poly[::-1]
    return poly

def tri_excess(a, b, c):
    """Signed spherical excess (Van Oosterom & Strackee, stable form)."""
    num = dot(a, cross(b - a, c - a))
    den = LD(1) + dot(a, b) + dot(b, c) + dot(c, a)
    return 2*np.arctan2(num, den)

def signed_area(poly):
    n = len(poly)
    if n < 3:
        return LD(0)
    return sum((tri_excess(poly[0], poly[i], poly[i+1]) for i in range(1, n-1)), LD(0))

def clip(poly, a, b):
    """Clip spherical polygon by half-space inside edge a->b of a CCW polygon."""
    n = edge_normal(a, b)
    out = []
    m = len(poly)
    for i in range(m):
        p = poly[i]; q = poly[(i+1) % m]
        dp = dot(n, p); dq = dot(n, q)
        if dp >= 0:
            out.append(p)
        if (dp > 0 and dq < 0) or (dp < 0 and dq > 0):
            # intersection of great circle (p,q) with plane n
            e = cross(p, q - p)          # normal of great circle pq
            x = normalize(cross(n, e))
            if dot(x, p + q) < 0:
                x = -x
            out.append(x)
    return out

def intersection_area(polyP, polyQ):
    P = orient([np.array(v, dtype=LD) for v in polyP])
    Q = orient([np.array(v, dtype=LD) for v in polyQ])
    poly = P
    for i in range(len(Q)):
        poly = clip(poly, Q[i], Q[(i+1) % len(Q)])
        if len(poly) < 3:
            return LD(0)
    return abs(signed_area(poly))

def quad_from_lonlat(lons, lats):
    return [unit_from_lonlat(lo, la) for lo, la in zip(lons, lats)]
