    """corners of a rotated square pixel of angular size `size` deg centred near lon0,lat0."""
    c, s = np.cos(rot), np.sin(rot)
    R = np.array([[c, -s], [s, c]])
    off = np.array([[-0.5, -0.5], [0.5, -0.5], [0.5, 0.5], [-0.5, 0.5]]) * size
    off = off @ R.T
    off[:, 0] += shift[0]*size
    off[:, 1] += shift[1]*size
    lons = lon0 + off[:, 0]/np.cos(lat0*d2r)
    lats = lat0 + off[:, 1]
    return lons, lats

