782	/*
783	 * Tests whether whether a point on an arc is
784	 * between two other points.
785	 */
786	int Between(Vec *v, Vec *a, Vec *b) {
787	  double abDot, avDot, bvDot;
788	
789	  abDot = Dot(a, b);
790	  avDot = Dot(a, v);
791	  bvDot = Dot(b, v);
792	
793	  if (avDot > abDot && bvDot > abDot)
794	    return TRUE;
795	  else
796	    return FALSE;
797	}

