cat > /workspace/task/source/reproject/spherical_intersect/overlapArea.c <<'CEOF'
/* Methods to compute pixel overlap areas on the sphere.
 *
 * Originally developed in 2003 / 2004 by John Good.
 *
 * The two pixels are treated as convex spherical polygons whose sides are
 * great circle arcs.  The polygon describing the region they have in common is
 * built by clipping the input pixel against the great circle half spaces
 * defined by the sides of the output pixel (the spherical equivalent of what
 * the plane-parallel flavour of this code, overlapAreaPP.c, does with
 * rectClip() / lineClip() in pixel space), and the solid angle of the result
 * is then obtained by adding up the signed spherical excess of a fan of
 * triangles.
 *
 * Both steps are written entirely in terms of *differences* between the
 * vertices that are involved, i.e. in terms of the small quantities of the
 * problem rather than in terms of positions measured from the centre of the
 * sphere.  This is what makes the result meaningful for real images: celestial
 * pixels are routinely many orders of magnitude smaller than a radian (an
 * arcsecond is 4.85e-6 rad, a milliarcsecond 4.85e-9 rad), so their solid
 * angles are far below the ~1e-16 rounding level of quantities of order unity.
 * Formulations that work with those quantities directly lose *all* of their
 * significant digits at that point.  Two classic examples, both of which used
 * to be used here:
 *
 *   - Girard's theorem, area = sum(interior angles) - (n - 2) * pi, computes
 *     the area as the difference between two numbers of order pi.  It is only
 *     usable while the area stays well above pi * DBL_EPSILON ~ 1e-15 sr, i.e.
 *     while the pixels are larger than about 0.1 arcsecond.  Below that the
 *     returned "areas" are pure rounding noise, which is why sub-arcsecond
 *     images ended up with overlap fractions well outside [0, 1].
 *
 *   - a fixed angular tolerance (a few nrad, say) used to decide whether a
 *     vertex is inside a pixel, on its edge, or outside it stops
 *     discriminating as soon as the pixels themselves are that small: every
 *     vertex looks as if it were on every edge.
 *
 * The formulations below instead have errors that are relative to the size of
 * the pixels, so they behave the same way for a 1 degree pixel and for a
 * microarcsecond pixel, and they contain no tolerance that is compared against
 * an absolute angular scale.  They are also free of global state, so they may
 * be called from several threads at once.
 */

#include <stdio.h>
#if defined(_MSC_VER)
  #define _USE_MATH_DEFINES
#endif
#include <float.h>
#include <math.h>
#include "mNaN.h"
#include "overlapArea.h"

// Constants

#define FALSE             0
#define TRUE              1

#if defined(DEBUG_OVERLAP_AREA)
    const int DEBUG = 10;
#else
    const int DEBUG = 0;
#endif

const double DEG_TO_RADIANS = M_PI / 180.;

const int NP = 4;
const int NQ = 4;

// Clipping a convex quadrilateral against the four sides of another one
// cannot produce more than eight vertices; the buffers are larger than that so
// that degenerate input cannot overrun them.

#define MAX_VERTICES     32

// A vertex whose distance from a side is no larger than this many rounding
// levels of the quantities the distance is computed from is taken to lie
// exactly *on* that side.  Note that this is a relative slack: it is scaled by
// the magnitudes of the vectors involved (see ClipToEdge()) and therefore
// shrinks with the pixels instead of swamping them.  It keeps corners and
// edges that are shared exactly (adjacent pixels of the same grid, or grids
// that share a reference point) from being resolved at random, and it can bias
// the area by no more than a few rounding levels of the area itself.

const double VERTEX_SLACK = 8. * DBL_EPSILON;

typedef struct vec {
  double x;
  double y;
  double z;
} Vec;

// Function prototypes

void Cross(Vec *v1, Vec *v2, Vec *v3);
double Dot(Vec *a, Vec *b);
double Normalize(Vec *v);
void Reverse(Vec *v);
void Difference(Vec *a, Vec *b, Vec *d);

double TriangleArea(Vec *a, Vec *b, Vec *c);
double PolygonArea(int nv, Vec *V);

int ClipToEdge(Vec *a, Vec *b, Vec *V, int nv, Vec *Vnew);
void ComputeIntersection(Vec *P, Vec *Q, Vec *V, int *nv);
void EnsureCounterClockWise(Vec *V);

void PrintPolygon(char *label, int nv, Vec *V);

/*
 * Sets up the polygons, runs the overlap computation, and returns the area of overlap.
 */
double computeOverlap(double *ilon, double *ilat, double *olon, double *olat,
                      int energyMode, double refArea, double *areaRatio) {
  int i;
  double area;
  Vec P[8], Q[8], V[MAX_VERTICES];
  int nv;

  *areaRatio = 1.;

  if (DEBUG >= 4) {
    printf("Input (P):\n");
    for (i = 0; i < NP; ++i)
      printf("%10.6f %10.6f\n", ilon[i], ilat[i]);

    printf("\nOutput (Q):\n");
    for (i = 0; i < NQ; ++i)
      printf("%10.6f %10.6f\n", olon[i], olat[i]);

    printf("\n");
    fflush(stdout);
  }

  for (i = 0; i < NP; ++i) {
    P[i].x = cos(ilon[i]) * cos(ilat[i]);
    P[i].y = sin(ilon[i]) * cos(ilat[i]);
    P[i].z = sin(ilat[i]);
  }

  for (i = 0; i < NQ; ++i) {
    Q[i].x = cos(olon[i]) * cos(olat[i]);
    Q[i].y = sin(olon[i]) * cos(olat[i]);
    Q[i].z = sin(olat[i]);
  }

  EnsureCounterClockWise(P);
  EnsureCounterClockWise(Q);

  // In "energy mode" the caller wants the area of the input pixel relative to
  // a reference area as well (it is used to convert between surface brightness
  // and energy); the overlap area itself is not affected by this.

  if (energyMode)
    *areaRatio = PolygonArea(NP, P) / refArea;

  ComputeIntersection(P, Q, V, &nv);

  area = PolygonArea(nv, V);

  // Two convex pixels cannot overlap by a negative amount; anything else can
  // only come from degenerate input (a pixel with no area, or coordinates that
  // are not defined at all).

  if (mNaN(area) || area < 0.)
    area = 0.;

  if (DEBUG >= 4) {
    printf("\ncomputeOverlap(): area = %13.6e [%d vertices]\n\n", area, nv);
    fflush(stdout);
  }

  return area;
}

/*
 * Make sure that the polygon is counter-clockwise (as seen from outside the
 * sphere).  The pixels are convex quadrilaterals, so the sign of their solid
 * angle tells us how they are wound, and reversing the winding of a
 * quadrilateral is just a matter of exchanging two opposite vertices.
 */
void EnsureCounterClockWise(Vec *V) {
  double tmp;

  if (PolygonArea(NP, V) < 0.) {
    tmp = V[2].x;
    V[2].x = V[0].x;
    V[0].x = tmp;
    tmp = V[2].y;
    V[2].y = V[0].y;
    V[0].y = tmp;
    tmp = V[2].z;
    V[2].z = V[0].z;
    V[0].z = tmp;
  }
}

/*
 * Find the polygon defining the area of overlap
 * between the two input polygons P and Q.
 *
 * Both polygons are assumed to be convex and counter-clockwise, so the region
 * they share is what is left of P after it has been clipped against each of
 * the great circle half spaces bounded by the sides of Q.  This handles every
 * configuration in the same way: pixels that cross each other, pixels that
 * touch along a shared side or at a single corner, and pixels that contain one
 * another (clipping P against a Q that lies inside it simply returns Q, and
 * clipping a P that lies inside Q returns P untouched).
 */
void ComputeIntersection(Vec *P, Vec *Q, Vec *V, int *nv) {
  Vec Vnew[MAX_VERTICES];
  int i, iq, iq_next, n;

  for (i = 0; i < NP; ++i)
    V[i] = P[i];

  n = NP;

  for (iq = 0; iq < NQ; ++iq) {
    iq_next = (iq + 1) % NQ;

    n = ClipToEdge(&Q[iq], &Q[iq_next], V, n, Vnew);

    // Fewer than three vertices means that the pixels have no area in common.

    if (n < 3) {
      if (DEBUG >= 4) {
        printf("ComputeIntersection(): no overlap "
               "(clipped away by side %d of Q)\n\n", iq);
        fflush(stdout);
      }

      *nv = 0;
      return;
    }

    for (i = 0; i < n; ++i)
      V[i] = Vnew[i];

    if (DEBUG >= 4)
      PrintPolygon("ComputeIntersection(): clipped", n, V);
  }

  *nv = n;
}

/*
 * Clip the polygon V against the great circle half space to the left of the
 * directed side a -> b and return the number of vertices of the clipped
 * polygon in Vnew.
 *
 * The half space is { v : (a x b) . v >= 0 }.  We evaluate the equivalent
 * form
 *
 *     (a x b) . v = (a x (b - a)) . (v - a)
 *
 * (the terms that are dropped all contain a twice and so vanish identically)
 * because b - a and v - a are the small quantities of the problem: they carry
 * the full significance of the vertex coordinates, while evaluating
 * (a x b) . v as written cancels the leading digits and leaves a result whose
 * error is the same size as a pixel.
 */
int ClipToEdge(Vec *a, Vec *b, Vec *V, int nv, Vec *Vnew) {
  int i, j, nvnew;
  Vec edge, normal, delta, crossing;
  double d[MAX_VERTICES], slack[MAX_VERTICES];
  double normalMag, s;

  Difference(b, a, &edge);
  Cross(a, &edge, &normal);

  normalMag = sqrt(Dot(&normal, &normal));

  for (i = 0; i < nv; ++i) {
    Difference(&V[i], a, &delta);

    d[i] = Dot(&normal, &delta);

    // The uncertainty of d[i] is set by the rounding of the vertex
    // coordinates themselves, which propagates into both factors of the dot
    // product; scaling the slack by their magnitudes makes the comparison
    // below independent of the size of the pixels.

    slack[i] = VERTEX_SLACK * normalMag * sqrt(Dot(&delta, &delta));
  }

  nvnew = 0;

  for (i = 0; i < nv; ++i) {
    j = (i + 1) % nv;

    // Vertices that are inside the half space, or on its boundary, are kept.

    if (d[i] >= -slack[i] && nvnew < MAX_VERTICES) {
      Vnew[nvnew] = V[i];
      ++nvnew;
    }

    // A crossing point is only needed when the two ends of the side are
    // strictly on opposite sides of the great circle: if either of them lies
    // on it, that vertex is itself the point where the boundary is crossed and
    // it has already been kept.

    if ((d[i] > slack[i] && d[j] < -slack[j])
        || (d[i] < -slack[i] && d[j] > slack[j])) {

      // The distance is a linear function of position and the plane goes
      // through the centre of the sphere, so the chord from V[i] to V[j]
      // crosses the plane exactly where the interpolated distance vanishes,
      // and normalizing that point puts it on the great circle through V[i]
      // and V[j].

      s = d[i] / (d[i] - d[j]);

      Difference(&V[j], &V[i], &delta);

      crossing.x = V[i].x + s * delta.x;
      crossing.y = V[i].y + s * delta.y;
      crossing.z = V[i].z + s * delta.z;

      Normalize(&crossing);

      if (nvnew < MAX_VERTICES) {
        Vnew[nvnew] = crossing;
        ++nvnew;
      }
    }
  }

  return nvnew;
}

/*
 * Solid angle of a spherical polygon, as the sum of the signed areas of the
 * triangles of a fan anchored on its first vertex.  The result is positive for
 * a counter-clockwise polygon and changes sign with the winding, and it is
 * zero (rather than noise) for degenerate polygons.
 */
double PolygonArea(int nv, Vec *V) {
  int i;
  double area;

  if (nv < 3)
    return 0.;

  area = 0.;

  for (i = 1; i < nv - 1; ++i)
    area += TriangleArea(&V[0], &V[i], &V[i + 1]);

  if (DEBUG >= 4) {
    PrintPolygon("PolygonArea()", nv, V);
    printf("PolygonArea(): area = %13.6e\n\n", area);
    fflush(stdout);
  }

  return area;
}

/*
 * Signed spherical excess of the triangle abc, i.e. its solid angle, positive
 * when the vertices are counter-clockwise.
 *
 * This is the formulation of Van Oosterom & Strackee (1983),
 *
 *     tan(E / 2) = a . (b x c) / (1 + a.b + b.c + c.a)
 *
 * with the triple product evaluated from the sides of the triangle,
 *
 *     a . (b x c) = a . ((b - a) x (c - a))
 *
 * which is an identity (the terms that are dropped contain a twice).  The two
 * expressions are equally exact in real arithmetic, but the second one is the
 * only usable one in floating point once the triangle is small: b - a and
 * c - a are exactly the size of the triangle, whereas b x c is a difference of
 * quantities of order one that returns nothing but rounding noise for a
 * triangle whose area is below ~1e-16.  The denominator is close to 4 for a
 * small triangle and needs no such care, and atan2() keeps the formula valid
 * up to a full hemisphere.
 */
double TriangleArea(Vec *a, Vec *b, Vec *c) {
  Vec ab, ac, cross;
  double numerator, denominator;

  Difference(b, a, &ab);
  Difference(c, a, &ac);

  Cross(&ab, &ac, &cross);

  numerator = Dot(a, &cross);
  denominator = 1. + Dot(a, b) + Dot(b, c) + Dot(c, a);

  return 2. * atan2(numerator, denominator);
}

/*
 * Vector difference: d = a - b.
 */
void Difference(Vec *a, Vec *b, Vec *d) {
  d->x = a->x - b->x;
  d->y = a->y - b->y;
  d->z = a->z - b->z;
}

/*
 * Vector cross product.
 */
void Cross(Vec *v1, Vec *v2, Vec *v3) {
  v3->x = v1->y * v2->z - v2->y * v1->z;
  v3->y = -v1->x * v2->z + v2->x * v1->z;
  v3->z = v1->x * v2->y - v2->x * v1->y;
}

/*
 * Vector dot product.
 */
double Dot(Vec *a, Vec *b) {
  double sum = 0.0;

  sum = a->x * b->x + a->y * b->y + a->z * b->z;

  return sum;
}

/*
 * Normalize the vector
 */
double Normalize(Vec *v) {
  double len;

  len = sqrt(v->x * v->x + v->y * v->y + v->z * v->z);

  if (len == 0.)
    len = 1.;

  v->x = v->x / len;
  v->y = v->y / len;
  v->z = v->z / len;

  return len;
}

/*
 * Reverse the vector.
 */
void Reverse(Vec *v) {
  v->x = -v->x;
  v->y = -v->y;
  v->z = -v->z;
}

/*
 * Write out a polygon (debugging only).
 */
void PrintPolygon(char *label, int nv, Vec *V) {
  int i;
  double lon, lat;

  for (i = 0; i < nv; ++i) {
    lon = atan2(V[i].y, V[i].x) / DEG_TO_RADIANS;
    lat = asin(V[i].z) / DEG_TO_RADIANS;

    printf("%s: %3d [%13.6e,%13.6e,%13.6e] -> (%10.6f,%10.6f)\n", label, i,
           V[i].x, V[i].y, V[i].z, lon, lat);
  }

  printf("\n");
  fflush(stdout);
}
